theme_fig7_final <- function(
    base_size = 10.5
) {
  
  theme_classic(
    base_size = base_size
  ) +
    
    theme(
      
      plot.title =
        element_text(
          face = "bold",
          size = base_size + 1
        ),
      
      plot.subtitle =
        element_text(
          size = base_size - 0.4,
          margin = margin(
            b = 4
          )
        ),
      
      plot.caption =
        element_text(
          size = base_size - 1.5,
          hjust = 0,
          color = "grey30",
          margin = margin(
            t = 5
          )
        ),
      
      axis.title =
        element_text(
          face = "bold"
        ),
      
      axis.text =
        element_text(
          color = "black"
        ),
      
      strip.background =
        element_blank(),
      
      strip.text =
        element_text(
          face = "bold",
          size = base_size
        ),
      
      legend.title =
        element_text(
          face = "bold"
        ),
      
      legend.text =
        element_text(
          color = "black"
        ),
      
      plot.margin =
        margin(
          7,
          8,
          7,
          8
        )
    )
}


# =========================================================
# 8. Helper functions
# =========================================================

format_p <- function(p) {
  
  case_when(
    is.na(p) ~ "p = n/a",
    
    p < 0.001 ~
      "p < 0.001",
    
    TRUE ~
      paste0(
        "p = ",
        sprintf(
          "%.3f",
          p
        )
      )
  )
}


format_fdr <- function(q) {
  
  case_when(
    
    is.na(q) ~
      "FDR = n/a",
    
    q < 0.001 ~
      paste0(
        "FDR = ",
        format(
          q,
          scientific = TRUE,
          digits = 3
        )
      ),
    
    TRUE ~
      paste0(
        "FDR = ",
        sprintf(
          "%.3f",
          q
        )
      )
  )
}


save_plot_multi <- function(
    plot,
    filename_stub,
    width,
    height
) {
  
  ggsave(
    filename = file.path(
      dir_plots,
      paste0(
        filename_stub,
        ".pdf"
      )
    ),
    plot = plot,
    width = width,
    height = height,
    units = "in"
  )
  
  
  ggsave(
    filename = file.path(
      dir_plots,
      paste0(
        filename_stub,
        ".png"
      )
    ),
    plot = plot,
    width = width,
    height = height,
    units = "in",
    dpi = 300
  )
  
  
  ggsave(
    filename = file.path(
      dir_plots,
      paste0(
        filename_stub,
        ".tiff"
      )
    ),
    plot = plot,
    width = width,
    height = height,
    units = "in",
    dpi = 300,
    compression = "lzw"
  )
}


