# =========================================================
# 10. PANEL A official clone-level statistics
#
# Use official 56F_C FDR family:
#   response E
#   response NE
#
# Expected:
#   E  rho ~0.147, FDR ~2.91e-6
#   NE rho ~0.0414, FDR ~0.456
# =========================================================

panelA_stats_official <- official_cor %>%
  
  filter(
    qc_level ==
      "min100cells_min10persistent",
    
    scope_type ==
      "response",
    
    scope_name %in%
      c(
        "NE",
        "E"
      )
  ) %>%
  
  transmute(
    
    response_group =
      factor(
        scope_name,
        levels = c(
          "NE",
          "E"
        )
      ),
    
    n_clonotypes =
      as.integer(
        n
      ),
    
    rho =
      spearman_rho,
    
    p_value =
      p_value,
    
    fdr =
      p_adj_fdr,
    
    label =
      paste0(
        "rho = ",
        sprintf(
          "%.3f",
          spearman_rho
        ),
        "\n",
        format_fdr(
          p_adj_fdr
        ),
        "\nn = ",
        as.integer(
          n
        ),
        " clonotypes"
      )
  )


if (
  nrow(
    panelA_stats_official
  ) != 2
) {
  
  stop(
    paste0(
      "Expected exactly two official response rows ",
      "(E and NE) for min100cells_min10persistent."
    )
  )
}


